287	// -----------------------------------------------------------------------------
288	// PURE CONTRACT DECISION FUNCTIONS
289	// -----------------------------------------------------------------------------
290	
291	export function validateManifestCoverage(manifest) {
292	  const errors = [];
293	  if (!manifest) {
294	    return ['Manifest is empty or undefined'];
295	  }
296	
297	  const requirements = Array.isArray(manifest.requirements) ? manifest.requirements : [];
298	  const shards = Array.isArray(manifest.shards) ? manifest.shards : [];
299	
300	  if (requirements.length === 0) {
301	    errors.push('Manifest contains no requirements');
302	  }
303	
304	  if (shards.length === 0) {
305	    return ['Manifest contains no shards'];
306	  }
307	
308	  const allReqIds = [];
309	  const seenReqIds = new Set();
310	  const duplicateReqIds = new Set();
311	
312	  for (const req of requirements) {
313	    const id = typeof req === 'string' ? req.trim() : req?.id?.trim();
314	    if (!id) {
315	      errors.push('Manifest requirement has missing or empty id');
316	      continue;
317	    }
318	    if (seenReqIds.has(id)) {
319	      duplicateReqIds.add(id);
320	    }
321	    seenReqIds.add(id);
322	    allReqIds.push(id);
323	  }
324	
325	  if (duplicateReqIds.size > 0) {
326	    errors.push(`Duplicate requirement IDs in manifest: ${[...duplicateReqIds].join(', ')}`);
327	  }
328	
329	  const seenShardIds = new Set();
330	  const duplicateShardIds = new Set();
331	
332	  for (const shard of shards) {
333	    const shardId = shard.id?.trim();
334	    if (!shardId) {
335	      errors.push('Manifest shard has missing or empty id');
336	      continue;
337	    }
338	    if (seenShardIds.has(shardId)) {
339	      duplicateShardIds.add(shardId);
340	    }
341	    seenShardIds.add(shardId);
342	
343	    if (!shard.objective || typeof shard.objective !== 'string' || shard.objective.trim() === '') {
344	      errors.push(`Shard '${shardId}' has an empty or missing objective`);
345	    }
346	
347	    const isInfra = shard.kind === 'infrastructure' || shard.kind === 'support';
348	    const shardReqs = (shard.requirements || [])
349	      .map((r) => (typeof r === 'string' ? r.trim() : String(r).trim()))
350	      .filter(Boolean);
351	
352	    if (!isInfra && shardReqs.length === 0) {
353	      errors.push(`Non-infrastructure shard '${shardId}' has zero mapped requirements`);
354	    }
355	  }
356	
357	  if (duplicateShardIds.size > 0) {
358	    errors.push(`Duplicate shard IDs in manifest: ${[...duplicateShardIds].join(', ')}`);
359	  }
360	
361	  const allReqSet = new Set(allReqIds);
362	  const claimedReqSet = new Set();
363	  const unknownReqIds = new Set();
364	
365	  for (const shard of shards) {
366	    const shardId = shard.id?.trim() || 'unknown';
367	    const shardReqs = (shard.requirements || [])
368	      .map((r) => (typeof r === 'string' ? r.trim() : String(r).trim()))
369	      .filter(Boolean);
370	
371	    const shardSeenReqs = new Set();
372	    for (const reqId of shardReqs) {
373	      if (shardSeenReqs.has(reqId)) {
374	        errors.push(`Shard '${shardId}' contains duplicate requirement ID '${reqId}'`);
375	      }
376	      shardSeenReqs.add(reqId);
377	
378	      if (!allReqSet.has(reqId)) {
379	        unknownReqIds.add(reqId);
380	      }
381	      claimedReqSet.add(reqId);
382	    }
383	  }
384	
385	  const missingReqIds = allReqIds.filter((id) => !claimedReqSet.has(id));
386	
387	  if (missingReqIds.length > 0) {
388	    errors.push(`Unclaimed plan requirements (missing coverage): ${missingReqIds.join(', ')}`);
389	  }
390	
391	  if (unknownReqIds.size > 0) {
392	    errors.push(`Unknown requirement IDs claimed by shards: ${[...unknownReqIds].join(', ')}`);
393	  }
394	
395	  return errors;
396	}
397	
398	export function validateManifestOwnership(manifest) {
399	  const errors = [];
400	  if (!manifest || !Array.isArray(manifest.shards)) return errors;
401	
402	  const shards = manifest.shards;
403	  for (let i = 0; i < shards.length; i++) {
404	    const shardA = shards[i];
405	    const ownsA = shardA.owns || [];
406	
407	    for (let j = i + 1; j < shards.length; j++) {
408	      const shardB = shards[j];
409	      const ownsB = shardB.owns || [];
410	
411	      for (const pathA of ownsA) {
412	        for (const pathB of ownsB) {
413	          if (pathsOverlap(pathA, pathB)) {
414	            const isIsolatedA = shardA.isolation === 'worktree' || shardA.isolated === true;
415	            const isIsolatedB = shardB.isolation === 'worktree' || shardB.isolated === true;
416	            if (isIsolatedA || isIsolatedB) {
417	              continue;
418	            }
419	            errors.push(
420	              `Mutable ownership overlap between shard '${shardA.id}' and shard '${shardB.id}': ` +
421	              `'${pathA}' overlaps with '${pathB}'`
422	            );
423	          }
424	        }
425	      }
426	    }
427	  }
428	
429	  return errors;
430	}
431	
432	export function computeShardPriorities(manifest) {
433	  const priorityMap = new Map();
434	  if (!manifest || !Array.isArray(manifest.shards)) return priorityMap;
435	
436	  const shards = manifest.shards;
437	  const dependentsMap = new Map();
438	  for (const s of shards) {
439	    dependentsMap.set(s.id, new Set());
440	  }
441	
442	  for (const s of shards) {
443	    if (Array.isArray(s.dependencies)) {
444	      for (const depId of s.dependencies) {
445	        if (dependentsMap.has(depId)) {
446	          dependentsMap.get(depId).add(s.id);
447	        }
448	      }
449	    }
450	  }
451	
452	  for (const s of shards) {
453	    const visited = new Set();
454	    const queue = [...(dependentsMap.get(s.id) || [])];
455	    for (const d of queue) visited.add(d);
456	
457	    let head = 0;
458	    while (head < queue.length) {
459	      const curr = queue[head++];
460	      const nextDeps = dependentsMap.get(curr);
461	      if (nextDeps) {
462	        for (const nextId of nextDeps) {
463	          if (!visited.has(nextId)) {
464	            visited.add(nextId);
465	            queue.push(nextId);
466	          }
467	        }
468	      }
469	    }
470	    const transitiveDownstream = visited.size;
471	
472	    const risk = String(s.risk || 'medium').toLowerCase();
473	    let riskWeight = 2;
474	    if (risk === 'critical') riskWeight = 4;
475	    else if (risk === 'high') riskWeight = 3;
476	    else if (risk === 'low') riskWeight = 1;
477	
478	    const reqCount = Array.isArray(s.requirements) ? s.requirements.length : 0;
479	    const ownsCount = Array.isArray(s.owns) ? s.owns.length : 0;
480	    const acCount = Array.isArray(s.acceptanceCriteria) ? s.acceptanceCriteria.length : 0;
481	    const workCount = reqCount + ownsCount + acCount;
482	
483	    const priority = (transitiveDownstream * 10) + (riskWeight * 3) + workCount;
484	
485	    priorityMap.set(s.id, {
486	      priority,
487	      transitiveDownstream,
488	      riskWeight,
489	      workCount,
490	    });
491	  }
492	
493	  return priorityMap;
494	}
495	
496	export function shouldIsolateShard(shard, manifest) {
497	  if (!shard) return false;
498	  if (shard.isolation === 'none' || shard.isolated === false) {
499	    return false;
500	  }
501	  if (shard.isolation === 'worktree' || shard.isolated === true) {
502	    return true;
503	  }
504	  const kind = String(shard.kind || '').toLowerCase();
505	  if (kind === 'exploratory' || kind === 'migration') {
506	    return true;
507	  }
508	  if (manifest && Array.isArray(manifest.shards)) {
509	    const shardOwns = Array.isArray(shard.owns) ? shard.owns : [];
510	    for (const other of manifest.shards) {
511	      if (!other || other.id === shard.id) continue;
512	      const otherOwns = Array.isArray(other.owns) ? other.owns : [];
513	      for (const pA of shardOwns) {
514	        for (const pB of otherOwns) {
515	          if (pathsOverlap(pA, pB)) {
516	            return true;
517	          }
518	        }
519	      }
520	    }
521	  }
522	  return false;
523	}
524	
525	export function clusterIntegrationFindings(findings) {
526	  if (!Array.isArray(findings) || findings.length === 0) return [];
527	
528	  const validFindings = findings.filter(Boolean);
529	  const fileFindings = [];
530	  const globalFindings = [];
531	
532	  for (const f of validFindings) {
533	    const file = typeof f.file === 'string' ? f.file.trim() : '';
534	    if (!file || file.toLowerCase() === 'none' || file.toLowerCase() === 'unknown') {
535	      globalFindings.push(f);
536	    } else {
537	      fileFindings.push(f);
538	    }
539	  }
540	
541	  const n = fileFindings.length;
542	  const adj = Array.from({ length: n }, () => []);
543	
544	  for (let i = 0; i < n; i++) {
545	    for (let j = i + 1; j < n; j++) {
546	      if (pathsOverlap(fileFindings[i].file, fileFindings[j].file)) {
547	        adj[i].push(j);
548	        adj[j].push(i);
549	      }
550	    }
551	  }
552	
553	  const visited = new Set();
554	  const clusters = [];
555	
556	  for (let i = 0; i < n; i++) {
557	    if (visited.has(i)) continue;
558	    const component = [];
559	    const queue = [i];
560	    visited.add(i);
561	
562	    while (queue.length > 0) {
563	      const u = queue.shift();
564	      component.push(fileFindings[u]);
565	      for (const v of adj[u]) {
566	        if (!visited.has(v)) {
567	          visited.add(v);
568	          queue.push(v);
569	        }
570	      }
571	    }
572	
573	    const files = [...new Set(component.map((f) => f.file))];
574	    clusters.push({
575	      id: `cluster-${clusters.length + 1}`,
576	      files,
577	      findings: component,
578	    });
579	  }
580	
581	  if (globalFindings.length > 0) {
582	    const extractedFiles = [];
583	    const pathRegex = /(?:[a-zA-Z0-9_\-./]+\/[a-zA-Z0-9_\-./]+\.[a-zA-Z0-9]+)/g;
584	    for (const gf of globalFindings) {
585	      const text = `${gf.file || ''} ${gf.evidence || ''} ${gf.recommendedFix || ''}`;
586	      const matches = text.match(pathRegex) || [];
587	      for (const m of matches) {
588	        if (!m.startsWith('http') && !m.includes('//')) {
589	          extractedFiles.push(normalizePath(m));
590	        }
591	      }
592	    }
593	    const dedupedFiles = [...new Set(extractedFiles.filter(Boolean))];
594	    clusters.push({
595	      id: 'cluster-global',
596	      files: dedupedFiles,
597	      findings: globalFindings,
598	    });
599	  }
600	
601	  return clusters;
602	}
603	
604	export function buildShardPacket(shard, manifest) {
605	  if (!shard) return null;
606	
607	  const manifestReqs = Array.isArray(manifest?.requirements) ? manifest.requirements : [];
608	  const manifestReqMap = new Map();
609	  for (const req of manifestReqs) {
610	    if (typeof req === 'string') {
611	      const str = req.trim();
612	      manifestReqMap.set(str, str);
613	      const match = str.match(/^([A-Za-z0-9_-]+)[:\s\-\.](.*)$/);
614	      if (match) {
615	        const parsedId = match[1].trim();
616	        const parsedText = match[2].trim() || str;
617	        manifestReqMap.set(parsedId, parsedText);
618	      }
619	    } else if (req && typeof req === 'object') {
620	      const id = req.id ? String(req.id).trim() : '';
621	      const text =
622	        typeof req.description === 'string'
623	          ? req.description.trim()
624	          : typeof req.text === 'string'
625	          ? req.text.trim()
626	          : '';
627	      if (id) {
628	        manifestReqMap.set(id, text || id);
629	      }
630	    }
631	  }
632	
633	  let resolvedReqDetails = Array.isArray(shard.requirementDetails) ? [...shard.requirementDetails] : [];
634	  const shardReqIds = Array.isArray(shard.requirements) ? shard.requirements : [];
635	
636	  if (resolvedReqDetails.length === 0 && shardReqIds.length > 0) {
637	    for (const rid of shardReqIds) {
638	      const ridStr = String(rid).trim();
639	      const text = manifestReqMap.get(ridStr) || `Requirement ${ridStr}`;
640	      resolvedReqDetails.push({
641	        id: ridStr,
642	        text,
643	      });
644	    }
645	  }
646	
647	  return {
648	    id: shard.id,
649	    objective: shard.objective,
650	    kind: shard.kind || 'feature',
651	    isolation: shard.isolation || (shard.isolated ? 'worktree' : 'none'),
652	    owns: Array.isArray(shard.owns) ? shard.owns : [],
653	    antiOwns: Array.isArray(shard.antiOwns) ? shard.antiOwns : [],
654	    dependencies: Array.isArray(shard.dependencies) ? shard.dependencies : [],
655	    requirements: shardReqIds,
656	    requirementDetails: resolvedReqDetails,
657	    acceptanceCriteria: Array.isArray(shard.acceptanceCriteria) ? shard.acceptanceCriteria : [],
658	    risk: shard.risk || 'medium',
659	    testHints: Array.isArray(shard.testHints) ? shard.testHints : [],
660	  };
661	}
