/**
 * QCET Plan Executor - Canonical Schemas, Contracts, and Pure Decision Logic
 * Upholds Universal Invariant 1: One Capability, One Canonical Implementation.
 * Shared across Node tools, test harnesses, and workflow script generators.
 */

import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const pathMatcher = require('./canonical-path-matcher.cjs');

export const {
  normalizePath,
  stripWildcards,
  globToRegex,
  matchesOwnership,
  pathsOverlap,
  toRepoRelativePath,
  isExternalAbsolutePath,
} = pathMatcher;

// -----------------------------------------------------------------------------
// SCHEMAS
// -----------------------------------------------------------------------------

export const MANIFEST_SCHEMA = {
  type: 'object',
  required: ['summary', 'requirements', 'shards'],
  properties: {
    summary: { type: 'string' },
    requirements: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'description'],
        properties: {
          id: { type: 'string' },
          description: { type: 'string' },
        },
      },
    },
    shards: {
      type: 'array',
      items: {
        type: 'object',
        required: [
          'id',
          'objective',
          'owns',
          'antiOwns',
          'dependencies',
          'requirements',
          'acceptanceCriteria',
          'risk',
          'testHints',
        ],
        properties: {
          id: { type: 'string' },
          objective: { type: 'string', minLength: 1 },
          kind: {
            type: 'string',
            enum: ['feature', 'infrastructure', 'validation', 'support', 'exploratory', 'migration'],
          },
          isolation: {
            type: 'string',
            enum: ['none', 'worktree'],
          },
          owns: {
            type: 'array',
            items: { type: 'string' },
          },
          antiOwns: {
            type: 'array',
            items: { type: 'string' },
          },
          dependencies: {
            type: 'array',
            items: { type: 'string' },
          },
          requirements: {
            type: 'array',
            items: { type: 'string' },
          },
          acceptanceCriteria: {
            type: 'array',
            items: { type: 'string' },
          },
          requirementDetails: {
            type: 'array',
            items: {
              type: 'object',
              required: ['id', 'text'],
              properties: {
                id: { type: 'string' },
                text: { type: 'string' },
              },
            },
          },
          risk: {
            type: 'string',
            enum: ['low', 'medium', 'high', 'critical'],
          },
          testHints: {
            type: 'array',
            items: { type: 'string' },
          },
        },
      },
    },
  },
};

export const BUILDER_RESULT_SCHEMA = {
  type: 'object',
  required: ['status', 'changedFiles', 'testsRun', 'requirementsSatisfied'],
  properties: {
    status: {
      type: 'string',
      enum: ['completed', 'failed', 'blocked'],
    },
    changedFiles: {
      type: 'array',
      items: { type: 'string' },
    },
    testsRun: {
      type: 'array',
      items: {
        type: 'object',
        required: ['command', 'status'],
        properties: {
          command: { type: 'string' },
          status: { type: 'string', enum: ['passed', 'failed'] },
          output: { type: 'string' },
        },
      },
    },
    requirementsSatisfied: {
      type: 'array',
      items: { type: 'string' },
    },
    summary: { type: 'string' },
    blockers: {
      type: 'array',
      items: { type: 'string' },
    },
  },
};

export const SKEPTIC_RESULT_SCHEMA = {
  type: 'object',
  required: ['verdict', 'issues', 'testsRun', 'requirementsVerified'],
  properties: {
    verdict: {
      type: 'string',
      enum: ['pass', 'fail'],
    },
    issues: {
      type: 'array',
      items: {
        type: 'object',
        required: ['severity', 'file', 'description', 'evidence'],
        properties: {
          severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
          file: { type: 'string' },
          description: { type: 'string' },
          evidence: { type: 'string' },
          recommendedFix: { type: 'string' },
        },
      },
    },
    testsRun: {
      type: 'array',
      items: {
        type: 'object',
        required: ['command', 'status'],
        properties: {
          command: { type: 'string' },
          status: { type: 'string', enum: ['passed', 'failed'] },
          output: { type: 'string' },
        },
      },
    },
    requirementsVerified: {
      type: 'array',
      items: { type: 'string' },
    },
    summary: { type: 'string' },
  },
};

export const REPAIR_RESULT_SCHEMA = {
  type: 'object',
  required: ['status', 'changedFiles', 'issuesFixed', 'remainingIssues'],
  properties: {
    status: {
      type: 'string',
      enum: ['completed', 'failed', 'blocked'],
    },
    changedFiles: {
      type: 'array',
      items: { type: 'string' },
    },
    issuesFixed: {
      type: 'array',
      items: { type: 'string' },
    },
    remainingIssues: {
      type: 'array',
      items: { type: 'string' },
    },
    summary: { type: 'string' },
  },
};

export const INTEGRATION_REVIEW_SCHEMA = {
  type: 'object',
  required: ['verdict', 'findings', 'contractCompliance'],
  properties: {
    verdict: {
      type: 'string',
      enum: ['pass', 'fail'],
    },
    contractCompliance: {
      type: 'string',
      enum: ['full', 'partial', 'violated'],
    },
    findings: {
      type: 'array',
      items: {
        type: 'object',
