1	/**
2	 * QCET Plan Executor - Targeted Test Runner & Verification Deduplicator
3	 * Implements E06: Deterministic test file discovery for changed files,
4	 * validation of test file existence, and run-scoped check deduplication.
5	 */
6	
7	import fs from 'node:fs';
8	import path from 'node:path';
9	import { spawnSync, execSync } from 'node:child_process';
10	import { getRepoRoot } from './worktree-manager.mjs';
11	import { normalizePath } from './canonical-path-matcher.cjs';
12	
13	/**
14	 * Recursively find all test files in a directory.
15	 * @param {string} dir
16	 * @returns {string[]}
17	 */
18	export function findAllTestFiles(dir) {
19	  if (!fs.existsSync(dir)) return [];
20	  const entries = fs.readdirSync(dir, { withFileTypes: true });
21	  const files = [];
22	
23	  for (const entry of entries) {
24	    const fullPath = path.join(dir, entry.name);
25	    if (entry.isDirectory()) {
26	      // Exclude worktrees, dist, node_modules
27	      if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === '.claude') {
28	        continue;
29	      }
30	      files.push(...findAllTestFiles(fullPath));
31	    } else if (entry.isFile() && (entry.name.endsWith('.test.ts') || entry.name.endsWith('.spec.ts'))) {
32	      files.push(fullPath);
33	    }
34	  }
35	
36	  return files;
37	}
38	
39	/**
40	 * Discover targeted test files that correspond to changed files and test hints.
41	 * Guarantees every returned test file actually exists on disk.
42	 *
43	 * @param {string[]} changedFiles - Array of file paths
44	 * @param {Object} [options]
45	 * @param {string[]} [options.testHints] - Explicit test file hints from shard packet
46	 * @param {string} [options.rootDir] - Repo root directory
47	 * @returns {{ testFiles: string[], discoveredCount: number, usedHints: boolean }}
48	 */
49	export function discoverTargetedTests(changedFiles = [], options = {}) {
50	  const rootDir = options.rootDir || getRepoRoot();
51	  const testHints = Array.isArray(options.testHints) ? options.testHints : [];
52	  const allKnownTestPaths = findAllTestFiles(path.join(rootDir, 'tests')).map((p) =>
53	    normalizePath(path.relative(rootDir, p))
54	  );
55	
56	  const matchedTests = new Set();
57	
58	  // 1. Process explicit testHints first
59	  let usedHints = false;
60	  for (const hint of testHints) {
61	    const normHint = normalizePath(hint);
62	    const absPath = path.isAbsolute(hint) ? hint : path.join(rootDir, normHint);
63	    if (fs.existsSync(absPath)) {
64	      matchedTests.add(normHint);
65	      usedHints = true;
66	    }
67	  }
68	
69	  // 2. Process changed files
