export function parseDateParts(dateInput: unknown): { year: number; month: number; day: number } | null {
  if (!dateInput) return null;
  if (dateInput instanceof Date) {
    if (isNaN(dateInput.getTime())) return null;
    const formatter = new Intl.DateTimeFormat("en-CA", {
      timeZone: "Asia/Ho_Chi_Minh",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    });
    const formatted = formatter.format(dateInput); // "YYYY-MM-DD"
    const [y, m, d] = formatted.split("-").map((n) => parseInt(n, 10));
    if (isNaN(y) || isNaN(m) || isNaN(d)) return null;
    return {
      year: y,
      month: m,
      day: d,
    };
  }
  if (typeof dateInput === "number" && !isNaN(dateInput)) {
    return parseDateParts(new Date(dateInput));
  }
  if (typeof dateInput === "string") {
    const trimmed = dateInput.trim();
    if (!trimmed) return null;
    // Pure calendar date "YYYY-MM-DD" without time component
    if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) {
      const [y, m, d] = trimmed.split("-").map((n) => parseInt(n, 10));
      if (isNaN(y) || isNaN(m) || isNaN(d)) return null;
      return {
        year: y,
        month: m,
        day: d,
      };
    }
    // Datetime string with or without timezone
    const hasTimezone = /([zZ]|[+-]\d{2}(?::?\d{2})?)$/.test(trimmed);
    let d: Date;
    if (hasTimezone) {
      d = new Date(trimmed);
    } else if (trimmed.includes("T")) {
      d = new Date(trimmed + "+07:00");
    } else if (trimmed.includes(" ")) {
      d = new Date(trimmed.replace(" ", "T") + "+07:00");
    } else {
      d = new Date(trimmed);
    }
    if (isNaN(d.getTime())) {
      const match = trimmed.match(/^(\d{4})-(\d{2})-(\d{2})/);
      if (match) {
        return {
          year: parseInt(match[1], 10),
          month: parseInt(match[2], 10),
          day: parseInt(match[3], 10),
        };
      }
      return null;
    }
    return parseDateParts(d);
  }
  return null;
}

/**
 * Trích xuất chuỗi ngày định dạng YYYY-MM-DD theo múi giờ chuẩn ICT (Asia/Ho_Chi_Minh).
 */
export function extractDateString(val: unknown): string | null {
  if (!val) return null;
  const parts = parseDateParts(val);
  if (!parts) return null;
  return `${parts.year}-${pad(parts.month)}-${pad(parts.day)}`;
}

/**
 * Kiểm tra xem một ngày có phải là mốc ranh giới chu kỳ tháng vận hành học vụ (ngày 25 là bắt đầu, ngày 24 là kết thúc).
 * @param date - Date object hoặc chuỗi ngày ISO / chuỗi ngày có múi giờ
 * @returns { isStart: boolean, isEnd: boolean }
 */
export function isOperationalMonthBoundary(date: Date | string): { isStart: boolean; isEnd: boolean } {
  const parts = parseDateParts(date);
  if (!parts) {
    return { isStart: false, isEnd: false };
  }
  return {
    isStart: parts.day === 25,
    isEnd: parts.day === 24,
  };
}

