157	        const raw = fs.readFileSync(file, 'utf8');
158	        stateData = JSON.parse(raw);
159	        if (stateData) break;
160	      }
161	    } catch (_) {}
162	  }
163	
164	  // Also check QCET_ACTIVE_SHARDS env var (can be JSON string or file path)
165	  if (!stateData && process.env.QCET_ACTIVE_SHARDS) {
166	    const val = process.env.QCET_ACTIVE_SHARDS.trim();
167	    try {
