183	    const shardId = shard.id || shard.agentId || shard.agent_id;
184	    if (!shardId) return false;
185	    if (candidateIds.includes(shardId)) return true;
186	    for (const c of candidateIds) {
187	      if (shardId === c || shardId.startsWith(c + ':') || c.startsWith(shardId + ':')) return true;
188	    }
189	    return false;
190	  }
191	
192	  // Structure A: Array of shards
193	  if (Array.isArray(stateData)) {
194	    if (candidateIds.length > 0) {
195	      const match = stateData.find(matchesShard);
