export function parseDateParts(dateInput: unknown): { year: number; month: number; day: number } | null {
  if (!dateInput) return null;
  if (typeof dateInput === "string") {
    const trimmed = dateInput.trim();
    if (!trimmed) return null;
    const dateOnlyMatch = trimmed.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (dateOnlyMatch) {
      return {
        year: parseInt(dateOnlyMatch[1], 10),
        month: parseInt(dateOnlyMatch[2], 10),
        day: parseInt(dateOnlyMatch[3], 10),
      };
    }
    const d = new Date(trimmed);
    if (!isNaN(d.getTime())) {
      return parseDateParts(d);
    }
    const match = trimmed.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (match) {
      return {
        year: parseInt(match[1], 10),
        month: parseInt(match[2], 10),
        day: parseInt(match[3], 10),
      };
    }
    return null;
  }
  if (dateInput instanceof Date) {
    if (isNaN(dateInput.getTime())) return null;
    const formatter = new Intl.DateTimeFormat("en-CA", {
      timeZone: "Asia/Ho_Chi_Minh",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    });
    const parts = formatter.formatToParts(dateInput);
    const y = parts.find((p) => p.type === "year")?.value;
    const m = parts.find((p) => p.type === "month")?.value;
    const d = parts.find((p) => p.type === "day")?.value;
    if (!y || !m || !d) return null;
    return {
      year: parseInt(y, 10),
      month: parseInt(m, 10),
      day: parseInt(d, 10),
    };
  }
  return null;
}

/**
 * Checks if a given date is at an operational month boundary (24th or 25th).
 */
export function isOperationalMonthBoundary(date: Date | string): { isStart: boolean; isEnd: boolean } {
  const parts = parseDateParts(date);
  if (!parts) {
    return { isStart: false, isEnd: false };
  }
  return {
    isStart: parts.day === 25,
    isEnd: parts.day === 24,
  };
}

