import { describe, it } from "node:test";
import assert from "node:assert/strict";
import {
  parseDateParts,
  isOperationalMonthBoundary,
  getAcademicMonthInfo,
} from "../../src/lib/academic-calendar";

describe("Academic Calendar Boundary & Timezone Handling", () => {
  it("detects operational month boundaries", () => {
    // 2026-08-24 (previous cycle end, isStart: false, isEnd: true)
    const endBoundary = isOperationalMonthBoundary("2026-08-24");
    assert.deepEqual(endBoundary, { isStart: false, isEnd: true });

    // 2026-08-25 (new cycle start, isStart: true, isEnd: false)
    const startBoundary = isOperationalMonthBoundary("2026-08-25");
    assert.deepEqual(startBoundary, { isStart: true, isEnd: false });

    // Normal non-boundary dates (2026-09-10)
    const nonBoundary = isOperationalMonthBoundary("2026-09-10");
    assert.deepEqual(nonBoundary, { isStart: false, isEnd: false });
  });

  it("properly handles ISO datetime strings with timezone offsets in Asia/Ho_Chi_Minh", () => {
    // Datetime string with timezone offset: 2026-08-25T00:00:00+07:00
    const startWithTz = isOperationalMonthBoundary("2026-08-25T00:00:00+07:00");
    assert.deepEqual(startWithTz, { isStart: true, isEnd: false });

    // UTC equivalent of 2026-08-25 00:00:00+07:00 is 2026-08-24 17:00:00Z
    const startUtc = isOperationalMonthBoundary("2026-08-24T17:00:00Z");
    assert.deepEqual(startUtc, { isStart: true, isEnd: false });

    // UTC equivalent of 2026-08-24 23:59:59+07:00 is 2026-08-24 16:59:59Z
    const endUtc = isOperationalMonthBoundary("2026-08-24T16:59:59Z");
    assert.deepEqual(endUtc, { isStart: false, isEnd: true });
  });

  it("handles leap-year February transitions correctly", () => {
    // 2024 leap year
    assert.deepEqual(isOperationalMonthBoundary("2024-02-24"), { isStart: false, isEnd: true });
    assert.deepEqual(isOperationalMonthBoundary("2024-02-25"), { isStart: true, isEnd: false });
    assert.deepEqual(isOperationalMonthBoundary("2024-02-29"), { isStart: false, isEnd: false });

    // 2028 leap year
    assert.deepEqual(isOperationalMonthBoundary("2028-02-24"), { isStart: false, isEnd: true });
    assert.deepEqual(isOperationalMonthBoundary("2028-02-25"), { isStart: true, isEnd: false });
    assert.deepEqual(isOperationalMonthBoundary("2028-02-29"), { isStart: false, isEnd: false });
  });

  it("preserves inclusivity across month boundaries for getAcademicMonthInfo", () => {
    // 2026-08-24 belongs to Month 8 of 2025-2026
    const m8 = getAcademicMonthInfo("2026-08-24");
    assert.equal(m8.monthNumber, 8);
    assert.equal(m8.academicYear, "2025-2026");
    assert.equal(m8.startDate, "2026-07-25");
    assert.equal(m8.endDate, "2026-08-24");

    // 2026-08-25 belongs to Month 9 of 2026-2027
    const m9 = getAcademicMonthInfo("2026-08-25");
    assert.equal(m9.monthNumber, 9);
    assert.equal(m9.academicYear, "2026-2027");
    assert.equal(m9.startDate, "2026-08-25");
    assert.equal(m9.endDate, "2026-09-24");

    // 2024-02-24 belongs to Month 2 of 2023-2024
    const febInfo = getAcademicMonthInfo("2024-02-24");
    assert.equal(febInfo.monthNumber, 2);
    assert.equal(febInfo.academicYear, "2023-2024");
    assert.equal(febInfo.startDate, "2024-01-25");
    assert.equal(febInfo.endDate, "2024-02-24");

    // 2024-02-25 belongs to Month 3 of 2023-2024
    const marInfo = getAcademicMonthInfo("2024-02-25");
    assert.equal(marInfo.monthNumber, 3);
    assert.equal(marInfo.academicYear, "2023-2024");
    assert.equal(marInfo.startDate, "2024-02-25");
    assert.equal(marInfo.endDate, "2024-03-24");

    // 2024-02-29 belongs to Month 3 of 2023-2024
    const leapDayInfo = getAcademicMonthInfo("2024-02-29");
    assert.equal(leapDayInfo.monthNumber, 3);
    assert.equal(leapDayInfo.academicYear, "2023-2024");
  });
});

